import {NebulaRenderer,presets} from './renderer.js';
const $=id=>document.getElementById(id);let settings={...presets.veil},renderer,raf,last=0,time=0,dirty=true,dead=false;
const ranges=['density','scale','turbulence','dust','emission'];
function sync(){for(const key of [...ranges,'seed','colorA','colorB'])$(key).value=settings[key];for(const key of ranges)$(key+'Out').value=Number(settings[key]).toFixed(2);dirty=true;}
function read(){for(const key of ranges)settings[key]=Number($(key).value);settings.seed=Math.max(0,Math.min(999999,Number($('seed').value)||0));for(const key of ['colorA','colorB'])settings[key]=$(key).value;sync();}
function fit(){if(!renderer)return;const box=$('nebula').getBoundingClientRect();const q=$('quality').value;const factor=q==='draft'?.45:q==='cinema'?Math.min(devicePixelRatio,1.25):.65;$('nebula').width=Math.max(1,Math.round(box.width*factor));$('nebula').height=Math.max(1,Math.round(box.height*factor));settings.steps=q==='draft'?32:q==='cinema'?80:48;dirty=true;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('preset').onchange=()=>{settings={...presets[$('preset').value]};time=0;sync();fit();$('sceneTitle').textContent=$('preset').selectedOptions[0].textContent.split(' /')[0];};
for(const key of [...ranges,'seed','colorA','colorB'])$(key).addEventListener('input',read);
$('randomize').onclick=()=>{settings.seed=crypto.getRandomValues(new Uint32Array(1))[0]%1000000;time=0;sync();};
$('quality').onchange=fit;$('motion').onchange=()=>{last=0;dirty=true;};$('typography').onchange=()=>{$('typeSample').hidden=!$('typography').checked;document.querySelector('.caption').hidden=$('typography').checked;};
$('export').onclick=()=>download(new Blob([JSON.stringify({schema:'aether-nebula-v1',...settings},null,2)],{type:'application/json'}),'aether-nebula-'+settings.seed+'.json');
$('import').onclick=()=>$('recipeFile').click();$('recipeFile').onchange=async()=>{const file=$('recipeFile').files[0];if(!file)return;try{if(file.size>16384)throw Error('Recipe is too large');const data=JSON.parse(await file.text());if(data.schema!=='aether-nebula-v1')throw Error('Unknown recipe format');for(const key of [...ranges,'seed']){const input=$(key),value=data[key];if(!Number.isFinite(value)||value<Number(input.min)||value>Number(input.max))throw Error('Invalid '+key);}for(const key of ['colorA','colorB'])if(!/^#[0-9a-f]{6}$/i.test(data[key]))throw Error('Invalid colour');settings=Object.fromEntries([...ranges,'seed','colorA','colorB'].map(k=>[k,data[k]]));time=0;sync();fit();$('notice').textContent='Recipe loaded.';}catch(error){$('notice').textContent=error.message;}finally{$('recipeFile').value='';}};
$('png').onclick=()=>{if(!renderer)return;renderer.render(settings,time);$('nebula').toBlob(blob=>{if(blob)download(blob,'aether-nebula-'+settings.seed+'.png');else $('notice').textContent='Image export unavailable.';},'image/png');};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.preview').requestFullscreen();}catch{$('notice').textContent='Fullscreen unavailable.';}};
const observer=new ResizeObserver(fit);observer.observe($('nebula'));document.addEventListener('visibilitychange',()=>{last=0;dirty=true;});
function fail(message){$('backend').textContent='WEBGPU UNAVAILABLE';$('error').hidden=false;$('error').textContent=message;}
sync();try{renderer=new NebulaRenderer();await renderer.initialize($('nebula'));renderer.onError=message=>{dead=true;fail(message);};$('backend').textContent='● WEBGPU / VOLUMETRIC';fit();function frame(now){if(dead)return;const evolving=$('motion').checked&&!matchMedia('(prefers-reduced-motion: reduce)').matches;if(!document.hidden&&(dirty||evolving)){if(evolving&&last)time+=Math.min((now-last)/1000,.05);renderer.render(settings,time);$('renderInfo').textContent=`${$('nebula').width} × ${$('nebula').height} / ${settings.steps} VOLUME SAMPLES / SEED ${settings.seed}`;dirty=false;}last=now;raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);}catch(error){renderer?.dispose();fail(error.message);}
window.addEventListener('pagehide',event=>{if(!event.persisted){dead=true;cancelAnimationFrame(raf);observer.disconnect();renderer?.dispose();}});
